+}
+
+// Signed reciprocal division (Hacker's Delight, chapter 10). Compute the
+// multiplier with unsigned 64-bit arithmetic; the emitted multiply takes
+// the signed high half. Restrict this path to positive non-power divisors.
+fn reciprocal(divisor: Int) -> [Int] {
+    let d = u64(divisor); let top = 9223372036854775808u64
+    let nc = top - 1u64 - top % d
+    let mut q1 = top / nc; let mut r1 = top % nc
+    let mut q2 = top / d; let mut r2 = top % d
+    let mut p = 63
+    for {
+        p = p + 1
+        q1 = ints.wrapping_mul(q1, 2u64); r1 = r1 * 2u64
+        if r1 >= nc { q1 = ints.wrapping_add(q1, 1u64); r1 = r1 - nc }
+        q2 = ints.wrapping_mul(q2, 2u64); r2 = r2 * 2u64
+        if r2 >= d { q2 = ints.wrapping_add(q2, 1u64); r2 = r2 - d }
+        let delta = d - r2
+        if q1 > delta || q1 == delta && r1 != 0u64 { break }
+    }
+    let unsigned = ints.wrapping_add(q2, 1u64)
+    let mut signed = 0
+    if unsigned >= top { signed = -9223372036854775808 + int(unsigned - top) } else { signed = int(unsigned) }
+    return [signed, p - 64]
+}
+
+fn constant_division(o: mut Out, i: ir.Inst) -> Bool {
+    if i.op != ir.Op.Div && i.op != ir.Op.Rem && i.op != ir.Op.DivChk && i.op != ir.Op.RemChk { return false }
+    if o.locs[i.b].kind != 2 { return false }
+    let d = o.locs[i.b].off
+    if d <= 1 || (d & (d - 1)) == 0 { return false }
+    let magic = reciprocal(d)
+    let a = source(mut o, i.a, "x9")
+    constant(mut o, "x10", magic[0])
+    emit(mut o, "smulh x11, " + a + ", x10")
+    if magic[0] < 0 { emit(mut o, "add x11, x11, " + a) }
+    if magic[1] > 0 { emit(mut o, "asr x11, x11, #" + num(magic[1])) }
+    // Round toward zero, including the most negative Int.
+    emit(mut o, "add x11, x11, x11, lsr #63")
+    if i.op == ir.Op.Rem || i.op == ir.Op.RemChk {
+        constant(mut o, "x10", d)
+        emit(mut o, "msub x11, x11, x10, " + a)
+    }
+    put(mut o, i.dst, "x11")
+    return true
